mapper.sql:
FROM lectures
JOIN courses ON lectures.course_id = courses.id
JOIN users ON lectures.professor_id = users.id


        AND courses.name LIKE CONCAT('%', #{courseName}, '%')


        AND users.name LIKE CONCAT('%', #{professorName}, '%')


        AND lectures.year = #{year}


        AND lectures.semester = #{semester}


        AND courses.code = #{courseCode}
